<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Image Watermark Tool','description'=>'Add a text watermark to an image locally in your browser.','url'=>'https://smarttoolz.in/tools/image-watermark/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Image Watermark</h1><p>Add a text watermark and download the image.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="image/*"><input id="t" value="SmartToolz" placeholder="Watermark text"><button id="go" class="tool-btn">Add Watermark</button><a id="d" class="tool-btn" hidden download="watermarked.png">Download</a><canvas id="c" style="max-width:100%;margin-top:15px"></canvas></div></section></main><script>go.onclick=()=>{let f=document.getElementById('f').files[0];if(!f)return;let i=new Image;i.onload=()=>{c.width=i.width;c.height=i.height;let x=c.getContext('2d');x.drawImage(i,0,0);x.font=Math.max(18,i.width/20)+'px sans-serif';x.fillStyle='rgba(255,255,255,.75)';x.fillText(t.value,30,c.height-30);c.toBlob(b=>{d.href=URL.createObjectURL(b);d.hidden=false},'image/png')};i.src=URL.createObjectURL(f)}</script><?php smarttoolz_tool_page_end(); ?>